def preserve_account_data_and_last_login(apps, schema_editor):
    database = schema_editor.connection.alias
    Persona = apps.get_model("inventario", "Persona")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    AccessRecord = apps.get_model("inventario", "RegistroAcceso")

    for person in Persona.objects.using(database).exclude(
        django_user_id__isnull=True
    ).iterator():
        user = User.objects.using(database).get(pk=person.django_user_id)
        fields_to_update = []
        if not user.first_name:
            user.first_name = person.nombre
            fields_to_update.append("first_name")
        if not user.last_name:
            user.last_name = " ".join(
                name
                for name in (person.apellido_paterno, person.apellido_materno)
                if name
            )[:150]
            fields_to_update.append("last_name")
        if not user.email:
            user.email = person.email
            fields_to_update.append("email")
        if fields_to_update:
            user.save(using=database, update_fields=fields_to_update)

    AccessRecord.objects.using(database).bulk_create(
        [
            AccessRecord(
                usuario_id=user.pk,
                nombre_usuario=user.username,
                inicio=user.last_login,
            )
            for user in User.objects.using(database)
            .exclude(last_login__isnull=True)
            .iterator()
        ]
    )


